INSERT INTO `listening_audio`
  (`question_id`, `audio_url`, `transcript`, `duration_seconds`, `audio_total_seconds`, `audio_start_seconds`, `audio_end_seconds`, `question_start_seconds`, `question_end_seconds`, `group_key`, `listening_type`, `lrc_content`, `created_at`, `updated_at`)
VALUES (
  @q01, '/audio/exams/listening-cet6-2022-12-1.mp3', 'Conversation One\n对话一\n\nM: How''s your dissertation going?\n男：你的论文进展如何？\n\nI''m proofreading my first draft and will submit it to my professor tomorrow.\n我正在校对我的初稿，明天会提交给我的教授。\n\nW: Oh, I haven''t even started writing mine yet, so I''m really worried about finishing by the end of next semester.\n女：哦，我甚至还没有开始写。所以我真的很担心下个学期末完不成。\n\nM: You mean you haven''t even begun yours yet? The final draft is due in five months.\n男：你是说你还没开始?还有五个月就要交终稿了。\n\nW: Of course I''ve started it, but I can''t get to the writing yet as I haven''t found enough resources to use, so I''m still researching the topic.\n女：我当然已经开始了，但我还没有开始写作，因为我还没有找到足够的资源来使用，所以我还在研究这个话题。\n\nM: Maybe the problem is the way you''re doing your research.\n男：也许问题出在你做研究的方式上。\n\nI started by talking to my professor about where to look for information.\n我在开始前先和我的教授讨论了去哪里找信息。\n\nAnd based on that, I found books in the library and a lot of reputable journal articles on the Internet.\n基于此，我在图书馆找到了参考书，并在网上找到了许多知名的期刊文章。\n\nW: I''ve tried all that, but don''t have enough to write the dissertation as my department''s minimum length is 70 pages.\n女：我已经都尝试过了，但不够用来写论文，因为我们学院要求论文至少要写 70 页。\n\nI think the problem is that my topic isn''t viable.\n我认为问题是我的题目不可行。\n\nAnd honestly, my professor did warn me at the beginning that I might not be able to find enough material.\n老实说，我的教授一开始确实警告过我，说我可能无法找到足够的材料。\n\nBut I was so interested in the topic that I didn''t let his advice to turn me.\n但我对这个话题非常感兴趣，以至于他的建议并没有让我转变。\n\nM: Well, I suggest you find a new topic.\n男：好吧，我建议你找一个新话题。\n\nAfter all, our professors are here to guide us, so it''s best to listen to them.\n毕竟，我们的教授在这里指导我们，所以最好听从他们的意见。\n\nW: In retrospect, I wish I had listened to him, but I didn''t.\n女：回想起来，我真希望我听了他的话，但我没有。\n\nAnd now I don''t want to give up my topic as I''ve already invested so much time and energy.\n现在我不想放弃我的题目，因为我已经投入了大量的时间和精力。\n\nM: If you''re committed to your current topic, maybe you could make some adjustments rather than abandon it completely. What is your topic?\n男：如果你坚持你现在的题目，也许你可以做一些调整，而不是完全放弃它。你的题目是什么？\n\nW: It''s "Depictions of Femininity and Folklore from the South of the Country".\n女：《关于我国南方女性的气质和民间传说的描述》。\n\nM: That''s pretty narrow. You could find more material if you made the topic broader, maybe by including other kinds of depictions.\n男：那相当狭窄了。如果把题目扩大，你可以找到更多的材料，也许可以加入其他类型的描述。\n\nW: Broadening the topic is a great idea. I''ll start by including folklore from other regions of the country.\n女：扩大题目是一个好主意。我可以从将其他地区的民间传说加进来开始。\n\nQuestions 1 to 4 are based on the conversation you have just heard.\n请根据你刚刚听到的对话回答问题1到4。\n\n1. What does the woman say about her dissertation?\n1. 关于自己的论文，女士说了什么？\n\n2. What does the man say about his professor?\n2. 关于自己的教授，男士说了什么？\n\n3. What does the woman say about her professor?\n3. 关于自己的教授，女士说了什么？\n\n4. What do we learn the woman will do to complete her dissertation?\n4. 我们了解到女士为了完成论文会做什么？', 120, 1635, 33.00, 152.72, 157.84, 175.06, 'cet6-2022-12-1-g01', 'LONG_DIALOGUE', '[00:33.00]Conversation One｜对话一\n[00:35.65]M: How''s your dissertation going?｜男：你的论文进展如何？\n[00:37.87]I''m proofreading my first draft and will submit it to my professor tomorrow.｜我正在校对我的初稿，明天会提交给我的教授。\n[00:42.93]W: Oh, I haven''t even started writing mine yet, so I''m really worried about finishing by the end of next semester.｜女：哦，我甚至还没有开始写。所以我真的很担心下个学期末完不成。\n[00:50.58]M: You mean you haven''t even begun yours yet? The final draft is due in five months.｜男：你是说你还没开始?还有五个月就要交终稿了。\n[00:56.06]W: Of course I''ve started it, but I can''t get to the writing yet as I haven''t found enough resources to use, so I''m still researching the topic.｜女：我当然已经开始了，但我还没有开始写作，因为我还没有找到足够的资源来使用，所以我还在研究这个话题。\n[01:05.40]M: Maybe the problem is the way you''re doing your research.｜男：也许问题出在你做研究的方式上。\n[01:08.68]I started by talking to my professor about where to look for information.｜我在开始前先和我的教授讨论了去哪里找信息。\n[01:13.32]And based on that, I found books in the library and a lot of reputable journal articles on the Internet.｜基于此，我在图书馆找到了参考书，并在网上找到了许多知名的期刊文章。\n[01:20.48]W: I''ve tried all that, but don''t have enough to write the dissertation as my department''s minimum length is 70 pages.｜女：我已经都尝试过了，但不够用来写论文，因为我们学院要求论文至少要写 70 页。\n[01:29.26]I think the problem is that my topic isn''t viable.｜我认为问题是我的题目不可行。\n[01:33.38]And honestly, my professor did warn me at the beginning that I might not be able to find enough material.｜老实说，我的教授一开始确实警告过我，说我可能无法找到足够的材料。\n[01:40.22]But I was so interested in the topic that I didn''t let his advice to turn me.｜但我对这个话题非常感兴趣，以至于他的建议并没有让我转变。\n[01:45.51]M: Well, I suggest you find a new topic.｜男：好吧，我建议你找一个新话题。\n[01:48.29]After all, our professors are here to guide us, so it''s best to listen to them.｜毕竟，我们的教授在这里指导我们，所以最好听从他们的意见。\n[01:53.57]W: In retrospect, I wish I had listened to him, but I didn''t.｜女：回想起来，我真希望我听了他的话，但我没有。\n[01:58.61]And now I don''t want to give up my topic as I''ve already invested so much time and energy.｜现在我不想放弃我的题目，因为我已经投入了大量的时间和精力。\n[02:04.53]M: If you''re committed to your current topic, maybe you could make some adjustments rather than abandon it completely. What is your topic?｜男：如果你坚持你现在的题目，也许你可以做一些调整，而不是完全放弃它。你的题目是什么？\n[02:12.89]W: It''s "Depictions of Femininity and Folklore from the South of the Country".｜女：《关于我国南方女性的气质和民间传说的描述》。\n[02:18.04]M: That''s pretty narrow. You could find more material if you made the topic broader, maybe by including other kinds of depictions.｜男：那相当狭窄了。如果把题目扩大，你可以找到更多的材料，也许可以加入其他类型的描述。\n[02:26.40]W: Broadening the topic is a great idea. I''ll start by including folklore from other regions of the country.｜女：扩大题目是一个好主意。我可以从将其他地区的民间传说加进来开始。\n[02:32.72]Questions 1 to 4 are based on the conversation you have just heard.｜请根据你刚刚听到的对话回答问题1到4。\n[02:37.84]1. What does the woman say about her dissertation?｜1. 关于自己的论文，女士说了什么？\n[02:55.06]2. What does the man say about his professor?｜2. 关于自己的教授，男士说了什么？\n[03:11.68]3. What does the woman say about her professor?｜3. 关于自己的教授，女士说了什么？\n[03:29.48]4. What do we learn the woman will do to complete her dissertation?｜4. 我们了解到女士为了完成论文会做什么？', NOW(), NOW()
)
ON DUPLICATE KEY UPDATE
  `audio_url` = VALUES(`audio_url`),
