INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q04, 'What do we learn the woman will do to complete her dissertation?', '{"A":"Change her research methodology.","B":"Narrow down her dissertation topic.","C":"Consult her professor more.","D":"Follow the man''s advice."}', 'D', '】细节推断题。男士认为女士的论文题目太过狭窄，如果将题目扩大可能会找到更多资料。根据句(4)可知，女士认为扩大题目是个好主意, 她会将对其他地区的民间传说的描述囊括进来。由此可知，女士会听从男士的建议。因此答案为 D )。 Questions 5 to 8 are based on the conversation you have just heard. W： Today, on Book Talk, we are lucky enough to host John Robbins and discuss his new book, Why Americans Are Fat and How We Can Lose Weight. (5-D John isn''t just a respected writer； he''s also one of the rare celebrity authors writing about science today. M： Thanks for having me, Rebecca, but I''m hardly a celebrity. W： That''s very modest of you to say, (5-2Considering that your four books have sold a total of seven million copies worldwide, and they''ve been translated into 12 different languages. What makes people so fascinated with your work? M： (6)Well, people read my books because more than 60% of Americans are overweight or obese. And other countries are facing similar problems. Basically, we all want t', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q04
);

