INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q05, 'What does the woman say about the man in her introduction?', '{"A":"He has translated 12 books.","B":"He is a well-known nutritionist.","C":"His books sell well worldwide.","D":"His latest book sold a million copies."}', 'C', '】细节推断题。句（5-1）中女士介绍说，约翰不仅是一位受人尊敬的作家, 还是当今为数不多的撰写科学类文书的名人作家之一。根据句（5-2）可知, 男士的 4 部著作在全球总共售出了 700 万册， 并被翻译成 12 种不同的语言。由此可知, 男士的著作畅销全世界。因此答案为 C）。', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q05
);

INSERT INTO `listening_audio`
  (`question_id`, `audio_url`, `transcript`, `duration_seconds`, `audio_total_seconds`, `audio_start_seconds`, `audio_end_seconds`, `question_start_seconds`, `question_end_seconds`, `group_key`, `listening_type`, `lrc_content`, `created_at`, `updated_at`)
VALUES (
  @q05, '/audio/exams/listening-cet6-2022-12-1.mp3', 'Conversation Two\n对话二\n\nW: Today, on Book Talk, we are lucky enough to host John Robbins and discuss his new book, Why Americans Are Fat and How We Can Lose Weight.\n女：今天，在《书论》节目上，我们有幸邀请到约翰·罗宾斯，并讨论他的新书《为什么美国人很胖以及我们如何减肥》。\n\nJohn isn''t just a respected writer; he''s also one of the rare celebrity authors writing about science today.\n约翰不仅是一位受人尊敬的作家，他还是当今为数不多的科学领域的名人作家之一。\n\nM: Thanks for having me, Rebecca, but I''m hardly a celebrity.\n男：谢谢你邀请我，丽贝卡，但我算不上名人。\n\nW: That''s very modest of you to say, considering that your four books have sold a total of seven million copies worldwide, and they''ve been translated into 12 different languages.\n女：就你的四部著作在全球总共售出了700万册，并被翻译成12种不同的语言而言，你这么说太谦虚了。\n\nWhat makes people so fascinated with your work?\n是什么让人们对你的作品如此着迷？\n\nM: Well, people read my books because more than 60% of Americans are overweight or obese.\n男：嗯，人们读我的书是因为超过60%的美国人超重或肥胖。\n\nAnd other countries are facing similar problems.\n其他国家也面临类似的问题。\n\nBasically, we all want to know how to fix things.\n总的来说，我们都想知道如何解决问题。\n\nW: We certainly do.\n女：我们的确想知道如何解决。\n\nI''ve read your new book and it''s fabulous, especially when it comes to the way you make difficult science easy for laymen to understand.\n我读了你的新书，它很棒，尤其是你的方式让外行人理解晦涩的科学时更容易。\n\nThat''s no small achievement.\n这是一个不小的成就。\n\nM: I''m glad to hear you find my work accessible, because I was worried when I wrote it that discussing the science might make the book more suited for a specialist audience.\n男：我很高兴听到你说发现我的作品很容易理解，因为我在写作时很担心讨论科学可能会让这本书更适合专业读者。\n\nMy last book was written primarily for the medical community.\n我的上一本书主要是为医学界写的。\n\nBut this time, I want to help ordinary people take control of their weight.\n但这一次，我想帮助普通人控制自己的体重。\n\nW: And how do you suggest they do that?\n女：那你建议他们如何做到这一点？\n\nCan you give us the basics of your advice for people who want to lose weight?\n你能给我们一些你对想要减肥的人的一些基本建议吗？\n\nM: Briefly, I argue that every person needs to consider their metabolism and eat what suits their body''s needs.\n男：简单说，我认为每个人都需要考虑自己的新陈代谢，吃适合自己身体需求的东西。\n\nI don''t advocate one single diet.\n我不提倡单一饮食。\n\nSome people should eat more carbohydrates than others.\n有些人应该比其他人摄入更多的碳水化合物。\n\nAnd different people need different amounts of protein and fat.\n不同的人对蛋白质和脂肪的需要量不同。\n\nW: But you do have some recommendations for everyone, including eating ten servings of vegetables and three of fruit a day.\n女：但你确实有一些适合每个人的建议，包括每天吃10份蔬菜和3份水果。\n\nWe''ll talk about those recommendations next, but now we need to take a short break for a message from our sponsor.\n接下来我们会讨论这些建议，但是现在我们需要休息一下，听听赞助商的留言。\n\nQuestions 5 to 8 are based on the conversation you have just heard.\n请根据你刚刚听到的对话回答问题5到8。\n\n5. What does the woman say about the man in her introduction?\n5. 关于男士，女士在其介绍中说了什么？\n\n6. What has motivated the man to write his books?\n6. 是什么促使男士去写书？\n\n7. Who does the man say his last book was mainly written for?\n7. 男士说他的上一部书主要是为谁写的？\n\n8. What does the man recommend people do?\n8. 男士建议人们做什么？', 129, 1635, 227.86, 357.13, 361.74, 379.14, 'cet6-2022-12-1-g02', 'LONG_DIALOGUE', '[03:47.86]Conversation Two｜对话二\n[03:50.56]W: Today, on Book Talk, we are lucky enough to host John Robbins and discuss his new book, Why Americans Are Fat and How We Can Lose Weight.｜女：今天，在《书论》节目上，我们有幸邀请到约翰·罗宾斯，并讨论他的新书《为什么美国人很胖以及我们如何减肥》。\n[04:01.46]John isn''t just a respected writer; he''s also one of the rare celebrity authors writing about science today.｜约翰不仅是一位受人尊敬的作家，他还是当今为数不多的科学领域的名人作家之一。\n[04:10.05]M: Thanks for having me, Rebecca, but I''m hardly a celebrity.｜男：谢谢你邀请我，丽贝卡，但我算不上名人。\n[04:14.14]W: That''s very modest of you to say, considering that your four books have sold a total of seven million copies worldwide, and they''ve been translated into 12 different languages.｜女：就你的四部著作在全球总共售出了700万册，并被翻译成12种不同的语言而言，你这么说太谦虚了。\n[04:25.65]What makes people so fascinated with your work?｜是什么让人们对你的作品如此着迷？\n[04:29.18]M: Well, people read my books because more than 60% of Americans are overweight or obese.｜男：嗯，人们读我的书是因为超过60%的美国人超重或肥胖。\n[04:36.60]And other countries are facing similar problems.｜其他国家也面临类似的问题。\n[04:39.48]Basically, we all want to know how to fix things.｜总的来说，我们都想知道如何解决问题。\n[04:43.23]W: We certainly do.｜女：我们的确想知道如何解决。\n[04:44.97]I''ve read your new book and it''s fabulous, especially when it comes to the way you make difficult science easy for laymen to understand.｜我读了你的新书，它很棒，尤其是你的方式让外行人理解晦涩的科学时更容易。\n[04:53.40]That''s no small achievement.｜这是一个不小的成就。\n[04:55.78]M: I''m glad to hear you find my work accessible, because I was worried when I wrote it that discussing the science might make the book more suited for a specialist audience.｜男：我很高兴听到你说发现我的作品很容易理解，因为我在写作时很担心讨论科学可能会让这本书更适合专业读者。\n[05:06.22]My last book was written primarily for the medical community.｜我的上一本书主要是为医学界写的。\n[05:10.34]But this time, I want to help ordinary people take control of their weight.｜但这一次，我想帮助普通人控制自己的体重。\n[05:15.69]W: And how do you suggest they do that?｜女：那你建议他们如何做到这一点？\n[05:18.37]Can you give us the basics of your advice for people who want to lose weight?｜你能给我们一些你对想要减肥的人的一些基本建议吗？\n[05:22.90]M: Briefly, I argue that every person needs to consider their metabolism and eat what suits their body''s needs.｜男：简单说，我认为每个人都需要考虑自己的新陈代谢，吃适合自己身体需求的东西。\n[05:30.86]I don''t advocate one single diet.｜我不提倡单一饮食。\n[05:33.85]Some people should eat more carbohydrates than others.｜有些人应该比其他人摄入更多的碳水化合物。\n[05:37.37]And different people need different amounts of protein and fat.｜不同的人对蛋白质和脂肪的需要量不同。\n[05:40.77]W: But you do have some recommendations for everyone, including eating ten servings of vegetables and three of fruit a day.｜女：但你确实有一些适合每个人的建议，包括每天吃10份蔬菜和3份水果。\n[05:49.48]We''ll talk about those recommendations next, but now we need to take a short break for a message from our sponsor.｜接下来我们会讨论这些建议，但是现在我们需要休息一下，听听赞助商的留言。\n[05:57.13]Questions 5 to 8 are based on the conversation you have just heard.｜请根据你刚刚听到的对话回答问题5到8。\n[06:01.74]5. What does the woman say about the man in her introduction?｜5. 关于男士，女士在其介绍中说了什么？\n[06:19.14]6. What has motivated the man to write his books?｜6. 是什么促使男士去写书？\n[06:37.61]7. Who does the man say his last book was mainly written for?｜7. 男士说他的上一部书主要是为谁写的？\n[06:55.45]8. What does the man recommend people do?｜8. 男士建议人们做什么？', NOW(), NOW()
)
ON DUPLICATE KEY UPDATE
  `audio_url` = VALUES(`audio_url`),
  `transcript` = VALUES(`transcript`),
  `duration_seconds` = VALUES(`duration_seconds`),
  `audio_total_seconds` = VALUES(`audio_total_seconds`),
  `audio_start_seconds` = VALUES(`audio_start_seconds`),
  `audio_end_seconds` = VALUES(`audio_end_seconds`),
  `question_start_seconds` = VALUES(`question_start_seconds`),
  `question_end_seconds` = VALUES(`question_end_seconds`),
