INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q06, 'What has motivated the man to write his books?', '{"A":"The desire of Americans to try exotic cuisines.","B":"The demand for information about food safety.","C":"The fact that over half of Americans are overweight.","D":"The fact that science books are difficult to read."}', 'C', '】细节推断题。女士问男士是什么让人们对他的书作如此着迷。男士在句（6）中回答，人们读他的书是因为超过 60%的美国人超重或肥胖，其他国家也面临类似的问题。总的来说，大家都想知道如何解决问题。也就是说, 超过一半美国人都超重的事实让人们都想知道如何解决这个问题，这也就驱动了男士去写相关的书。因此答案为 C）。', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q06
);

