INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q10, 'How have medical professionals tried to fight obesity?', '{"A":"By focusing on the nutrients in different foods.","B":"By emphasizing the diversity of food.","C":"By stressing pleasing aesthetics of food.","D":"By winning the support of marketing professors."}', 'A', '】细节辨认题。根据句（17）可知，医疗专业人员试图通过关注不同食物中的营养成分和强调碳水化合物、脂肪、糖和卡路里等的含量来对抗肥胖流行病。因此答案为 A）。', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q10
);

