INSERT INTO `question_info`
  (`external_key`, `module_type`, `target_level`, `difficulty_level`, `question_type`, `source`, `ai_generated`, `usage_count`, `is_deleted`, `created_at`, `updated_at`)
SELECT
  'cet6-2022-12-1-q23', 4, 'CET6', 4, 'CHOICE', 'IMPORT', 0, 0, 0, NOW(), NOW()
WHERE NOT EXISTS (
