INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q16, 'What does the speaker say about the coins collected from New York City''s park fountains?', '{"A":"They are occasionally retrieved by curious tourists.","B":"They are regularly donated to charity organizations.","C":"They are mostly used for the fountains5 maintenance.","D":"They are usually used as wages for fountain cleaners."}', 'C', '】细节辨认题。句（23）中明确提到, 在纽约市，从公园里的喷泉中收集的硬币通常用于喷泉的维护。因此答案为 C）。', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q16
);

