INSERT INTO `question_content`
  (`question_id`, `stem`, `options`, `correct_answer`, `analysis`, `created_at`, `updated_at`)
SELECT
  @q17, 'What do we learn about the money collected from Rome''s Trevi Fountain?', '{"A":"It is invested in a series of businesses.","B":"It is used exclusively for its maintenance.","C":"It is used to run a supermarket for the needy.","D":"It is estimated to be about $ 40,000 a month."}', 'C', '】细节辨认题。讲座中提到, 数百年来都有游客把硬币扔进罗马著名的特雷维喷泉, 罗马官英语菌的笔记员要求每晚都要清理喷泉，据报道, 每天都会收集到高达 4 000 美元的世界各地的零钱。根据句 （24）可知，每天晚上收集到的大部分钱都用于一家为有需要的人经营的超市。因此答案为 C）。', NOW(), NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM `question_content` WHERE `question_id` = @q17
);

